export type DiffLineType = "unchanged" | "added" | "removed";

export interface DiffWordSpan {
  text: string;
  changed: boolean;
}

export interface DiffLine {
  type: DiffLineType;
  /** 1-indexed line number in the original text. null for added lines. */
  originalLineNumber: number | null;
  /** 1-indexed line number in the modified text. null for removed lines. */
  modifiedLineNumber: number | null;
  content: string;
  /**
   * Word-level diff spans, computed lazily (only for changed lines that pair with
   * a corresponding removed/added counterpart) — not populated on every line upfront.
   */
  wordSpans?: DiffWordSpan[];
}

export type DiffHunkKind = "unchanged" | "change" | "conflict";

export interface DiffHunk {
  id: string;
  kind: DiffHunkKind;
  lines: DiffLine[];
  /** Only for kind "conflict" — the three sides being reconciled. */
  conflict?: {
    base: DiffLine[];
    ours: DiffLine[];
    theirs: DiffLine[];
  };
}

export type ConflictChoice = "ours" | "theirs" | "both" | "base";

export type DiffViewMode = "unified" | "split";

export interface DiffViewerConfig {
  viewMode?: DiffViewMode; // default "split"
  /** Lines of unchanged context to show around a change before folding. Default 3. */
  contextLines?: number;
  /** Compute word-level highlighting inside changed line pairs. Default true. */
  wordDiff?: boolean;
  /** Enable virtualization above this line count. Default 500. */
  virtualizeThreshold?: number;
}

export interface DiffEngineResult {
  hunks: DiffHunk[];
  stats: { additions: number; deletions: number; conflicts: number };
}

export interface MergeEditorContextValue {
  hunks: DiffHunk[];
  stats: DiffEngineResult["stats"];
  resolutions: Record<string, ConflictChoice>;
  collapsedContextIds: Set<string>;
  viewMode: DiffViewMode;
  config: Required<DiffViewerConfig>;

  resolveConflict: (hunkId: string, choice: ConflictChoice) => void;
  resolveAll: (choice: ConflictChoice) => void;
  toggleContext: (hunkId: string) => void;
  setViewMode: (mode: DiffViewMode) => void;
  /** Reconstructs the final text from unresolved+resolved hunks. */
  getMergedText: () => string;
  /** True once every conflict hunk has a resolution. */
  isFullyResolved: () => boolean;
}

export type MyersOp<T> =
  | { type: "equal"; aIndex: number; bIndex: number; value: T }
  | { type: "delete"; aIndex: number; value: T }
  | { type: "insert"; bIndex: number; value: T };

/**
 * Classic Myers O(ND) shortest-edit-script diff. Generic over tokens so the
 * same implementation drives both line-level diffing (tokens = lines) and
 * word-level diffing inside a changed line pair (tokens = words).
 */
export function myersDiff<T>(a: T[], b: T[], equal: (x: T, y: T) => boolean = (x, y) => x === y): MyersOp<T>[] {
  const N = a.length;
  const M = b.length;
  const max = N + M;

  if (max === 0) return [];

  let v = new Map<number, number>([[1, 0]]);
  const trace: Map<number, number>[] = [];

  let found = false;
  for (let d = 0; d <= max && !found; d++) {
    trace.push(new Map(v));
    for (let k = -d; k <= d; k += 2) {
      let x: number;
      const vkMinus1 = v.get(k - 1) ?? -Infinity;
      const vkPlus1 = v.get(k + 1) ?? -Infinity;

      if (k === -d || (k !== d && vkMinus1 < vkPlus1)) {
        x = vkPlus1;
      } else {
        x = vkMinus1 + 1;
      }

      let y = x - k;
      while (x < N && y < M && equal(a[x], b[y])) {
        x++;
        y++;
      }

      v.set(k, x);

      if (x >= N && y >= M) {
        found = true;
        break;
      }
    }
  }

  // Backtrack through the trace to recover the edit script, in reverse.
  const ops: MyersOp<T>[] = [];
  let x = N;
  let y = M;

  for (let d = trace.length - 1; d >= 0; d--) {
    const vAtD = trace[d];
    const k = x - y;
    const vkMinus1 = vAtD.get(k - 1) ?? -Infinity;
    const vkPlus1 = vAtD.get(k + 1) ?? -Infinity;

    const prevK = k === -d || (k !== d && vkMinus1 < vkPlus1) ? k + 1 : k - 1;
    const prevX = vAtD.get(prevK) ?? 0;
    const prevY = prevX - prevK;

    while (x > prevX && y > prevY) {
      ops.push({ type: "equal", aIndex: x - 1, bIndex: y - 1, value: a[x - 1] });
      x--;
      y--;
    }

    if (d > 0) {
      if (x === prevX) {
        ops.push({ type: "insert", bIndex: y - 1, value: b[y - 1] });
      } else {
        ops.push({ type: "delete", aIndex: x - 1, value: a[x - 1] });
      }
    }

    x = prevX;
    y = prevY;
  }

  return ops.reverse();
}

import { myersDiff } from "./diff-algorithm";
import type { DiffEngineResult, DiffHunk, DiffLine, DiffViewerConfig, DiffWordSpan } from "./types";

function splitLines(text: string): string[] {
  if (text === "") return [];
  return text.split("\n");
}

function wordDiffPair(removed: string, added: string): { removedSpans: DiffWordSpan[]; addedSpans: DiffWordSpan[] } {
  // Split keeping whitespace as its own tokens so spans reconstruct the exact line.
  const tokenize = (s: string) => s.split(/(\s+)/).filter((t) => t.length > 0);
  const aTokens = tokenize(removed);
  const bTokens = tokenize(added);
  const ops = myersDiff(aTokens, bTokens);

  const removedSpans: DiffWordSpan[] = [];
  const addedSpans: DiffWordSpan[] = [];
  for (const op of ops) {
    if (op.type === "equal") {
      removedSpans.push({ text: op.value, changed: false });
      addedSpans.push({ text: op.value, changed: false });
    } else if (op.type === "delete") {
      removedSpans.push({ text: op.value, changed: true });
    } else {
      addedSpans.push({ text: op.value, changed: true });
    }
  }
  return { removedSpans, addedSpans };
}

/**
 * Flat line-level diff between two texts. Adjacent delete/insert runs are
 * paired up (by position within the run) for word-level highlighting.
 */
export function diffLines(a: string, b: string, wordDiff = true): DiffLine[] {
  const aLines = splitLines(a);
  const bLines = splitLines(b);
  const ops = myersDiff(aLines, bLines);

  const lines: DiffLine[] = [];
  let originalNum = 1;
  let modifiedNum = 1;

  // Buffer consecutive delete/insert runs so we can pair them for word-diff
  // before pushing them into the final line list, matching git's convention
  // of rendering all removals in a change block before all additions.
  let pendingRemoved: string[] = [];
  let pendingAdded: string[] = [];

  function flushPending() {
    if (pendingRemoved.length === 0 && pendingAdded.length === 0) return;

    const pairCount = wordDiff ? Math.min(pendingRemoved.length, pendingAdded.length) : 0;

    for (let i = 0; i < pendingRemoved.length; i++) {
      const content = pendingRemoved[i];
      const line: DiffLine = {
        type: "removed",
        originalLineNumber: originalNum++,
        modifiedLineNumber: null,
        content,
      };
      if (i < pairCount) {
        line.wordSpans = wordDiffPair(content, pendingAdded[i]).removedSpans;
      }
      lines.push(line);
    }

    for (let i = 0; i < pendingAdded.length; i++) {
      const content = pendingAdded[i];
      const line: DiffLine = {
        type: "added",
        originalLineNumber: null,
        modifiedLineNumber: modifiedNum++,
        content,
      };
      if (i < pairCount) {
        line.wordSpans = wordDiffPair(pendingRemoved[i], content).addedSpans;
      }
      lines.push(line);
    }

    pendingRemoved = [];
    pendingAdded = [];
  }

  for (const op of ops) {
    if (op.type === "equal") {
      flushPending();
      lines.push({
        type: "unchanged",
        originalLineNumber: originalNum++,
        modifiedLineNumber: modifiedNum++,
        content: op.value,
      });
    } else if (op.type === "delete") {
      pendingRemoved.push(op.value);
    } else {
      pendingAdded.push(op.value);
    }
  }
  flushPending();

  return lines;
}

let _hunkId = 0;
function uid() {
  _hunkId += 1;
  return `hunk_${_hunkId}`;
}

/**
 * Groups a flat DiffLine[] into hunks: runs of unchanged lines (collapsible,
 * with contextLines preserved uncollapsed at each boundary) alternating with
 * change hunks (the removed/added runs).
 */
export function buildHunks(lines: DiffLine[], contextLines: number): DiffHunk[] {
  const hunks: DiffHunk[] = [];
  let i = 0;

  while (i < lines.length) {
    if (lines[i].type === "unchanged") {
      const start = i;
      while (i < lines.length && lines[i].type === "unchanged") i++;
      const run = lines.slice(start, i);

      const isFileStart = start === 0;
      const isFileEnd = i === lines.length;

      if (run.length <= contextLines * 2 || isFileStart || isFileEnd) {
        // Short enough (or at a file boundary) — no point collapsing.
        hunks.push({ id: uid(), kind: "unchanged", lines: run });
      } else {
        // Keep context at both edges, collapse the middle into one foldable hunk.
        hunks.push({ id: uid(), kind: "unchanged", lines: run.slice(0, contextLines) });
        hunks.push({
          id: uid(),
          kind: "unchanged",
          lines: run.slice(contextLines, run.length - contextLines),
        });
        hunks.push({ id: uid(), kind: "unchanged", lines: run.slice(run.length - contextLines) });
      }
    } else {
      const start = i;
      while (i < lines.length && lines[i].type !== "unchanged") i++;
      hunks.push({ id: uid(), kind: "change", lines: lines.slice(start, i) });
    }
  }

  return hunks;
}

function countStats(lines: DiffLine[]) {
  let additions = 0;
  let deletions = 0;
  for (const l of lines) {
    if (l.type === "added") additions++;
    if (l.type === "removed") deletions++;
  }
  return { additions, deletions };
}

export function computeDiff(a: string, b: string, config: Required<DiffViewerConfig>): DiffEngineResult {
  const lines = diffLines(a, b, config.wordDiff);
  const hunks = buildHunks(lines, config.contextLines);
  const { additions, deletions } = countStats(lines);
  return { hunks, stats: { additions, deletions, conflicts: 0 } };
}

// ─── Three-way merge ──────────────────────────────────────────────────────────

interface ChangeRegion {
  baseStart: number; // inclusive, 0-indexed into baseLines
  baseEnd: number; // exclusive
  resultLines: string[];
}

function changeRegions(base: string[], other: string[]): ChangeRegion[] {
  const ops = myersDiff(base, other);
  const regions: ChangeRegion[] = [];

  let baseIdx = 0;
  let i = 0;
  while (i < ops.length) {
    if (ops[i].type === "equal") {
      baseIdx++;
      i++;
      continue;
    }
    const regionStart = baseIdx;
    const resultLines: string[] = [];
    while (i < ops.length && ops[i].type !== "equal") {
      const op = ops[i];
      if (op.type === "delete") baseIdx++;
      else resultLines.push(op.value);
      i++;
    }
    regions.push({ baseStart: regionStart, baseEnd: baseIdx, resultLines });
  }

  return regions;
}

function regionsOverlap(x: ChangeRegion, y: ChangeRegion): boolean {
  return x.baseStart < y.baseEnd && y.baseStart < x.baseEnd;
}

/**
 * Three-way diff: changes are computed independently against base for both
 * sides, then merged by base line range. A base range touched by only one
 * side auto-applies; a range touched by both sides with different results
 * becomes a conflict hunk requiring resolution.
 */
export function computeThreeWayDiff(
  base: string,
  ours: string,
  theirs: string,
  config: Required<DiffViewerConfig>,
): DiffEngineResult {
  const baseLines = splitLines(base);
  const oursRegions = changeRegions(baseLines, splitLines(ours));
  const theirsRegions = changeRegions(baseLines, splitLines(theirs));

  const hunks: DiffHunk[] = [];
  let conflicts = 0;
  let additions = 0;
  let deletions = 0;
  let cursor = 0;

  const allBoundaries = Array.from(
    new Set(
      [...oursRegions, ...theirsRegions].flatMap((r) => [r.baseStart, r.baseEnd]).concat([0, baseLines.length]),
    ),
  ).sort((a, b) => a - b);

  for (let bi = 0; bi < allBoundaries.length - 1; bi++) {
    const segStart = allBoundaries[bi];
    const segEnd = allBoundaries[bi + 1];
    if (segStart >= segEnd && baseLines.length > 0) continue;

    const oursHit = oursRegions.find((r) => r.baseStart <= segStart && r.baseEnd >= segEnd && r.baseEnd > r.baseStart);
    const theirsHit = theirsRegions.find(
      (r) => r.baseStart <= segStart && r.baseEnd >= segEnd && r.baseEnd > r.baseStart,
    );

    if (!oursHit && !theirsHit) {
      const unchangedContent = baseLines.slice(segStart, segEnd);
      if (unchangedContent.length === 0) continue;
      hunks.push({
        id: uid(),
        kind: "unchanged",
        lines: unchangedContent.map((content, idx) => ({
          type: "unchanged" as const,
          originalLineNumber: segStart + idx + 1,
          modifiedLineNumber: segStart + idx + 1,
          content,
        })),
      });
      cursor = segEnd;
      continue;
    }

    const oursResult = oursHit ? oursHit.resultLines : baseLines.slice(segStart, segEnd);
    const theirsResult = theirsHit ? theirsHit.resultLines : baseLines.slice(segStart, segEnd);
    const sameResult = oursResult.length === theirsResult.length && oursResult.every((l, idx) => l === theirsResult[idx]);

    if (sameResult || !oursHit || !theirsHit) {
      // Only one side changed this region (or both changed it identically) — auto-merge.
      const winner = oursHit ? oursResult : theirsResult;
      additions += winner.length;
      deletions += segEnd - segStart;
      hunks.push({
        id: uid(),
        kind: "change",
        lines: [
          ...baseLines.slice(segStart, segEnd).map((content) => ({
            type: "removed" as const,
            originalLineNumber: null,
            modifiedLineNumber: null,
            content,
          })),
          ...winner.map((content) => ({
            type: "added" as const,
            originalLineNumber: null,
            modifiedLineNumber: null,
            content,
          })),
        ],
      });
    } else {
      // Both sides changed this region differently — real conflict.
      conflicts++;
      hunks.push({
        id: uid(),
        kind: "conflict",
        lines: [],
        conflict: {
          base: baseLines.slice(segStart, segEnd).map((content) => ({
            type: "unchanged" as const,
            originalLineNumber: null,
            modifiedLineNumber: null,
            content,
          })),
          ours: oursResult.map((content) => ({
            type: "added" as const,
            originalLineNumber: null,
            modifiedLineNumber: null,
            content,
          })),
          theirs: theirsResult.map((content) => ({
            type: "added" as const,
            originalLineNumber: null,
            modifiedLineNumber: null,
            content,
          })),
        },
      });
    }

    cursor = segEnd;
  }

  void cursor;
  return { hunks, stats: { additions, deletions, conflicts } };
}

"use client";

import * as React from "react";
import type { MergeEditorContextValue } from "./types";

export const DiffViewerCtx = React.createContext<MergeEditorContextValue | null>(null);

export function useDiffViewerCtx(): MergeEditorContextValue {
  const ctx = React.useContext(DiffViewerCtx);
  if (!ctx) throw new Error("useDiffViewerCtx must be used inside DiffViewerRoot");
  return ctx;
}

"use client";

import * as React from "react";
import { DiffViewerCtx } from "./diff-viewer-context";
import { computeDiff, computeThreeWayDiff } from "./diff-engine";
import { DiffViewerLayout } from "./diff-viewer-layout";
import type { ConflictChoice, DiffHunk, DiffViewMode, DiffViewerConfig } from "./types";

const DEFAULT_CONFIG: Required<DiffViewerConfig> = {
  viewMode: "split",
  contextLines: 3,
  wordDiff: true,
  virtualizeThreshold: 500,
};

type TwoWayProps = { original: string; modified: string; base?: never; ours?: never; theirs?: never };
type ThreeWayProps = { base: string; ours: string; theirs: string; original?: never; modified?: never };

export type DiffViewerRootProps = (TwoWayProps | ThreeWayProps) & {
  config?: DiffViewerConfig;
  className?: string;
  /** Replace the default split/unified layout entirely. */
  children?: React.ReactNode;
  /** Called whenever every conflict hunk (merge mode) has been resolved. */
  onFullyResolved?: (mergedText: string) => void;
};

export function DiffViewerRoot(props: DiffViewerRootProps) {
  const { config: configInput, className, children, onFullyResolved } = props;
  const config: Required<DiffViewerConfig> = { ...DEFAULT_CONFIG, ...configInput };

  const isMerge = "base" in props && props.base !== undefined;

  const { hunks, stats } = React.useMemo(() => {
    if (isMerge) {
      const p = props as ThreeWayProps;
      return computeThreeWayDiff(p.base, p.ours, p.theirs, config);
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }
    const p = props as TwoWayProps;
    return computeDiff(p.original, p.modified, config);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isMerge, (props as TwoWayProps).original, (props as TwoWayProps).modified, (props as ThreeWayProps).base, (props as ThreeWayProps).ours, (props as ThreeWayProps).theirs, config.contextLines, config.wordDiff]);

  const defaultCollapsed = React.useMemo(
    () =>
      new Set(
        hunks
          .filter((h, idx) => h.kind === "unchanged" && idx > 0 && idx < hunks.length - 1)
          .map((h) => h.id),
      ),
    [hunks],
  );
  const [resolutions, setResolutions] = React.useState<Record<string, ConflictChoice>>({});
  const [collapsedContextIds, setCollapsedContextIds] = React.useState<Set<string>>(defaultCollapsed);
  React.useEffect(() => {
    setCollapsedContextIds(defaultCollapsed);
  }, [defaultCollapsed]);
  const [viewMode, setViewModeState] = React.useState<DiffViewMode>(config.viewMode);

  const resolveConflict = React.useCallback((hunkId: string, choice: ConflictChoice) => {
    setResolutions((prev) => ({ ...prev, [hunkId]: choice }));
  }, []);

  const resolveAll = React.useCallback(
    (choice: ConflictChoice) => {
      const next: Record<string, ConflictChoice> = {};
      hunks.forEach((h) => {
        if (h.kind === "conflict") next[h.id] = choice;
      });
      setResolutions(next);
    },
    [hunks],
  );

  const toggleContext = React.useCallback((hunkId: string) => {
    setCollapsedContextIds((prev) => {
      const next = new Set(prev);
      if (next.has(hunkId)) next.delete(hunkId);
      else next.add(hunkId);
      return next;
    });
  }, []);

  const isFullyResolved = React.useCallback(
    () => hunks.every((h) => h.kind !== "conflict" || resolutions[h.id] !== undefined),
    [hunks, resolutions],
  );

  const getMergedText = React.useCallback(() => {
    const lines: string[] = [];
    for (const h of hunks) {
      if (h.kind === "unchanged") {
        lines.push(...h.lines.map((l) => l.content));
      } else if (h.kind === "change") {
        lines.push(...h.lines.filter((l) => l.type !== "removed").map((l) => l.content));
      } else if (h.kind === "conflict" && h.conflict) {
        const choice = resolutions[h.id] ?? "base";
        if (choice === "ours") lines.push(...h.conflict.ours.map((l) => l.content));
        else if (choice === "theirs") lines.push(...h.conflict.theirs.map((l) => l.content));
        else if (choice === "both") {
          lines.push(...h.conflict.ours.map((l) => l.content));
          lines.push(...h.conflict.theirs.map((l) => l.content));
        } else {
          lines.push(...h.conflict.base.map((l) => l.content));
        }
      }
    }
    return lines.join("\n");
  }, [hunks, resolutions]);

  React.useEffect(() => {
    if (isFullyResolved() && hunks.some((h) => h.kind === "conflict")) {
      onFullyResolved?.(getMergedText());
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [resolutions]);

  const ctx = {
    hunks,
    stats,
    resolutions,
    collapsedContextIds,
    viewMode,
    config,
    resolveConflict,
    resolveAll,
    toggleContext,
    setViewMode: setViewModeState,
    getMergedText,
    isFullyResolved,
  };

  return (
    <DiffViewerCtx.Provider value={ctx}>
      {children ?? <DiffViewerLayout className={className} />}
    </DiffViewerCtx.Provider>
  );
}

DiffViewerRoot.displayName = "DiffViewerRoot";

export type { DiffHunk };

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { useDiffViewerCtx } from "./diff-viewer-context";
import { LazyHunk } from "./lazy-hunk";

export interface DiffViewerLayoutProps {
  className?: string;
}

export function DiffViewerLayout({ className }: DiffViewerLayoutProps) {
  const { hunks, stats, viewMode, setViewMode, resolveAll, config } = useDiffViewerCtx();

  const totalLines = React.useMemo(() => hunks.reduce((n, h) => n + h.lines.length, 0), [hunks]);
  const virtualize = totalLines > config.virtualizeThreshold;

  return (
    <div className={cn("flex flex-col overflow-hidden rounded-xl border border-border bg-card/60", className)}>
      <div className="flex items-center justify-between border-b border-border/60 px-3 py-2">
        <div className="flex items-center gap-3 text-[11px]">
          <span className="text-emerald-500">+{stats.additions}</span>
          <span className="text-red-500">−{stats.deletions}</span>
          {stats.conflicts > 0 && <span className="text-amber-500">{stats.conflicts} conflicts</span>}
        </div>

        <div className="flex items-center gap-2">
          {stats.conflicts > 0 && (
            <>
              <button
                type="button"
                onClick={() => resolveAll("ours")}
                className="text-[11px] text-muted-foreground hover:text-foreground"
              >
                Accept all ours
              </button>
              <button
                type="button"
                onClick={() => resolveAll("theirs")}
                className="text-[11px] text-muted-foreground hover:text-foreground"
              >
                Accept all theirs
              </button>
              <div className="h-3 w-px bg-border" />
            </>
          )}
          <div className="flex items-center gap-1 rounded-md border border-border bg-background/60 p-0.5">
            {(["split", "unified"] as const).map((m) => (
              <button
                key={m}
                type="button"
                onClick={() => setViewMode(m)}
                className={cn(
                  "rounded px-2 py-0.5 text-[11px] font-medium capitalize transition-colors",
                  viewMode === m ? "bg-primary/10 text-primary" : "text-muted-foreground hover:text-foreground",
                )}
              >
                {m}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="max-h-[420px] overflow-y-auto">
        {hunks.map((hunk) => (
          <LazyHunk key={hunk.id} hunk={hunk} active={virtualize} />
        ))}
      </div>
    </div>
  );
}

DiffViewerLayout.displayName = "DiffViewerLayout";

"use client";

import * as React from "react";
import { IconChevronDown, IconChevronUp } from "@tabler/icons-react";
import { cn } from "@/lib/utils";
import { useDiffViewerCtx } from "./diff-viewer-context";
import { DiffLineRow } from "./diff-line-row";
import type { DiffHunk, DiffLine } from "./types";

export interface DiffHunkViewProps {
  hunk: DiffHunk;
}

function pairForSplit(lines: DiffLine[]): { left: DiffLine | null; right: DiffLine | null }[] {
  const removed = lines.filter((l) => l.type === "removed");
  const added = lines.filter((l) => l.type === "added");
  const rows: { left: DiffLine | null; right: DiffLine | null }[] = [];
  const max = Math.max(removed.length, added.length);
  for (let i = 0; i < max; i++) {
    rows.push({ left: removed[i] ?? null, right: added[i] ?? null });
  }
  return rows;
}

export function DiffHunkView({ hunk }: DiffHunkViewProps) {
  const { viewMode, collapsedContextIds, toggleContext, resolveConflict, resolutions } = useDiffViewerCtx();

  if (hunk.kind === "unchanged") {
    const isCollapsed = collapsedContextIds.has(hunk.id);
    if (isCollapsed) {
      return (
        <button
          type="button"
          onClick={() => toggleContext(hunk.id)}
          className="flex w-full items-center gap-2 border-y border-border/60 bg-muted/30 px-3 py-1.5 text-[11px] text-muted-foreground hover:bg-muted/50"
        >
          <IconChevronDown size={12} />
          {hunk.lines.length} unchanged lines
        </button>
      );
    }

    return (
      <div>
        {hunk.lines.length > 6 && (
          <button
            type="button"
            onClick={() => toggleContext(hunk.id)}
            className="flex w-full items-center gap-2 border-b border-border/40 bg-muted/20 px-3 py-1 text-[10px] text-muted-foreground/70 hover:bg-muted/40"
          >
            <IconChevronUp size={11} />
            Collapse
          </button>
        )}
        {viewMode === "unified"
          ? hunk.lines.map((l, i) => <DiffLineRow key={i} line={l} showLineNumber={l.originalLineNumber} />)
          : hunk.lines.map((l, i) => (
              <div key={i} className="grid grid-cols-2">
                <DiffLineRow line={l} showLineNumber={l.originalLineNumber} />
                <DiffLineRow line={l} showLineNumber={l.modifiedLineNumber} />
              </div>
            ))}
      </div>
    );
  }

  if (hunk.kind === "change") {
    if (viewMode === "unified") {
      return (
        <div>
          {hunk.lines.map((l, i) => (
            <DiffLineRow key={i} line={l} showLineNumber={l.originalLineNumber ?? l.modifiedLineNumber} />
          ))}
        </div>
      );
    }
    const rows = pairForSplit(hunk.lines);
    return (
      <div>
        {rows.map((r, i) => (
          <div key={i} className="grid grid-cols-2">
            <DiffLineRow line={r.left} showLineNumber={r.left?.originalLineNumber ?? null} />
            <DiffLineRow line={r.right} showLineNumber={r.right?.modifiedLineNumber ?? null} />
          </div>
        ))}
      </div>
    );
  }

  // kind === "conflict"
  const conflict = hunk.conflict!;
  const resolution = resolutions[hunk.id];

  return (
    <div className="my-1 overflow-hidden rounded-lg border border-amber-500/40">
      <div className="flex items-center justify-between bg-amber-500/10 px-3 py-1.5">
        <span className="text-[11px] font-medium text-amber-600">Conflict</span>
        {resolution && (
          <span className="text-[10px] text-muted-foreground">
            Resolved: {resolution === "both" ? "both" : resolution}
          </span>
        )}
      </div>

      <div className="grid grid-cols-2 divide-x divide-border">
        <div>
          <div className="flex items-center justify-between border-b border-border/60 bg-muted/30 px-3 py-1">
            <span className="text-[10px] font-medium text-muted-foreground">Ours</span>
            <button
              type="button"
              onClick={() => resolveConflict(hunk.id, "ours")}
              className={cn(
                "rounded px-1.5 py-0.5 text-[10px] font-medium transition-colors",
                resolution === "ours" ? "bg-primary/20 text-primary" : "text-muted-foreground hover:text-foreground",
              )}
            >
              Accept
            </button>
          </div>
          {conflict.ours.map((l, i) => (
            <DiffLineRow key={i} line={l} showLineNumber={null} />
          ))}
        </div>

        <div>
          <div className="flex items-center justify-between border-b border-border/60 bg-muted/30 px-3 py-1">
            <span className="text-[10px] font-medium text-muted-foreground">Theirs</span>
            <button
              type="button"
              onClick={() => resolveConflict(hunk.id, "theirs")}
              className={cn(
                "rounded px-1.5 py-0.5 text-[10px] font-medium transition-colors",
                resolution === "theirs" ? "bg-primary/20 text-primary" : "text-muted-foreground hover:text-foreground",
              )}
            >
              Accept
            </button>
          </div>
          {conflict.theirs.map((l, i) => (
            <DiffLineRow key={i} line={l} showLineNumber={null} />
          ))}
        </div>
      </div>

      <div className="flex items-center gap-2 border-t border-border/60 bg-muted/20 px-3 py-1.5">
        <button
          type="button"
          onClick={() => resolveConflict(hunk.id, "both")}
          className={cn(
            "rounded px-2 py-1 text-[10px] font-medium transition-colors",
            resolution === "both" ? "bg-primary/20 text-primary" : "text-muted-foreground hover:text-foreground",
          )}
        >
          Accept both
        </button>
        <button
          type="button"
          onClick={() => resolveConflict(hunk.id, "base")}
          className={cn(
            "rounded px-2 py-1 text-[10px] font-medium transition-colors",
            resolution === "base" ? "bg-primary/20 text-primary" : "text-muted-foreground hover:text-foreground",
          )}
        >
          Keep original
        </button>
      </div>
    </div>
  );
}

